namespace RonSijm.FluidHumidifier.Factories.Glue;

public class CatalogFactory(string resourceName = null, Action<Humidifier.Glue.Catalog> factoryAction = null) : ResourceFactory<Humidifier.Glue.Catalog>(resourceName)
{

    internal List<InnerCatalogPrincipalPermissionsFactory> CreateTableDefaultPermissionsFactories { get; set; } = [];

    internal List<InnerCatalogPrincipalPermissionsFactory> CreateDatabaseDefaultPermissionsFactories { get; set; } = [];

    internal InnerCatalogTargetRedshiftCatalogFactory TargetRedshiftCatalogFactory { get; set; }

    internal InnerCatalogFederatedCatalogFactory FederatedCatalogFactory { get; set; }

    internal InnerCatalogCatalogPropertiesFactory CatalogPropertiesFactory { get; set; }

    protected override Humidifier.Glue.Catalog Create()
    {
        var catalogResult = CreateCatalog();
        factoryAction?.Invoke(catalogResult);

        return catalogResult;
    }

    private Humidifier.Glue.Catalog CreateCatalog()
    {
        var catalogResult = new Humidifier.Glue.Catalog
        {
            GivenName = InputResourceName,
        };

        return catalogResult;
    }
    public override void CreateChildren(Humidifier.Glue.Catalog result)
    {
        base.CreateChildren(result);

        result.CreateTableDefaultPermissions = CreateTableDefaultPermissionsFactories.Any() ? CreateTableDefaultPermissionsFactories.Select(x => x.Build()).ToList() : null;
        result.CreateDatabaseDefaultPermissions = CreateDatabaseDefaultPermissionsFactories.Any() ? CreateDatabaseDefaultPermissionsFactories.Select(x => x.Build()).ToList() : null;
        result.TargetRedshiftCatalog ??= TargetRedshiftCatalogFactory?.Build();
        result.FederatedCatalog ??= FederatedCatalogFactory?.Build();
        result.CatalogProperties ??= CatalogPropertiesFactory?.Build();
    }

} // End Of Class

